    if ((requested_a_m2 == NULL) || (duty == NULL)) {
        return ADCS_E_NULL;
    }
    duty->command = (adcs_vec3_t){0, 0, 0};
    duty->saturated_axes = 0U;

    if ((!adcs_is_finite_vec3(requested_a_m2)) || (!isfinite(full_scale_a_m2)) ||
        (full_scale_a_m2 <= 0.0) || (!isfinite(minimum_duty)) || (minimum_duty < 0.0) ||
        (minimum_duty > 1.0)) {
        duty->command = (adcs_vec3_t){0, 0, 0};
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    {
        double vals[3];
        double mvals[3];
        unint32 mask = 0U;
        int i;
        mvals[0] = requested_a_m2->x;
        mvals[1] = requested_a_m2->y;
        mvals[2] = requested_a_m2->z;
        for (i = 0; i < 3; i++) {
            double d = mvals[i] / full_scale_a_m2;
            double ad = fabs(d);
            double sign = (d < 0.0) ? -1.0 : 1.0;
            double mag;
            if (ad == 0.0) {
                mag = 0.0;
            } else if (ad < minimum_duty) {
                mag = minimum_duty;
                mask |= (unint32)(1U << i);
            } else if (ad <= 1.0) {
                mag = ad;
            } else {
                mag = 1.0;
            }
            if (mag == 0.0) {
                vals[i] = 0.0;
            } else {
                vals[i] = sign * mag;
            }
        }
        duty->command = (adcs_vec3_t){vals[0], vals[1], vals[2]};
        duty->saturated_axes = mask;
    }
    return ADCS_OK;
}

